(async () => {
  const { readFileSync, existsSync } = await import('node:fs');
  const csvPath = process.env.CSV_PATH;
  if (!csvPath) throw new Error('Missing CSV_PATH env var');
  if (!existsSync(csvPath)) throw new Error('CSV file does not exist at ' + csvPath);
  const content = readFileSync(csvPath, 'utf8');
  globalThis.csvContent = content;
})();

(async () => {
  const { default: Papa } = await import('papaparse');
  const content = globalThis.csvContent;
  if (typeof content !== 'string') throw new Error('csvContent not set');
  const result = Papa.parse(content, { header: false });
  if (result.errors && result.errors.length) throw new Error('CSV parse errors: ' + JSON.stringify(result.errors));
  const rows = result.data;
  if (!Array.isArray(rows) || rows.length === 0) throw new Error('No data parsed');
  const header = rows[0];
  const lines = [];
  lines.push('| ' + header.join(' | ') + ' |');
  lines.push('|' + header.map(() => '---').join('|') + '|');
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    lines.push('| ' + row.join(' | ') + ' |');
  }
  globalThis.markdown = lines.join('\n');
})();

(async () => {
  const output = { markdown: globalThis.markdown };
  if (typeof output.markdown !== 'string') throw new Error('markdown not generated');
  console.log(JSON.stringify(output));
})();
